using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using HeritageVR;using TMPro;using System.Linq;using System.IO;
public static class MuseumStorySetup{
 static TMP_Text Text(Transform parent,string name,string value,Vector3 pos,Vector2 size,float max){var source=Object.FindObjectOfType<MuseumExperience>().exhibitTitle;var t=Object.Instantiate(source,parent);t.name=name;t.transform.localPosition=pos;t.transform.localRotation=Quaternion.identity;t.transform.localScale=Vector3.one;t.text=value;t.rectTransform.sizeDelta=size;t.fontSize=max;t.enableAutoSizing=true;t.fontSizeMin=.5f;t.fontSizeMax=max;t.alignment=TextAlignmentOptions.Center;t.margin=Vector4.zero;t.lineSpacing=0;t.paragraphSpacing=0;t.rectTransform.pivot=new Vector2(.5f,.5f);t.color=Color.white;return t;}
 static TMP_Text Button(Transform parent,string label,string action,float x){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name="Story control • "+action;g.transform.SetParent(parent,false);g.transform.localPosition=new Vector3(x,-.66f,-.075f);g.transform.localScale=new Vector3(.55f,.17f,.025f);g.GetComponent<Renderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/HeritageVR/Materials/Information background.mat");g.AddComponent<MuseumAction>().action=action;var t=Text(g.transform,"Button label",label,new Vector3(0,0,-.6f),new Vector2(.5f,.14f),.72f);t.transform.localScale=new Vector3(1/.55f,1/.17f,1/.025f);return t;}
 [MenuItem("Museum/15 Add Stories and Narration")]
 public static void Apply(){
 EditorSceneManager.OpenScene("Assets/Scenes/UnifiedMuseum.unity");var e=Object.FindObjectOfType<MuseumExperience>();int i=0;
 foreach(var x in e.gallery.GetComponentsInChildren<MuseumExhibit>(true).OrderBy(x=>x.name)){x.description=MuseumArtifactSetup.Artifacts[i].description;string path="Assets/HeritageVR/Narration/Exhibit-"+(++i).ToString("00")+".wav";var importer=(AudioImporter)AssetImporter.GetAtPath(path);if(importer==null)throw new System.Exception("Missing audio "+path);var settings=importer.defaultSampleSettings;settings.loadType=AudioClipLoadType.CompressedInMemory;settings.compressionFormat=AudioCompressionFormat.Vorbis;settings.quality=.6f;importer.defaultSampleSettings=settings;importer.forceToMono=true;importer.SaveAndReimport();x.narration=AssetDatabase.LoadAssetAtPath<AudioClip>(path);x.narrationPages=new AudioClip[3];for(int part=1;part<=3;part++){string segment="Assets/HeritageVR/Narration/Exhibit-"+i.ToString("00")+"-Part-"+part+".wav";var ai=(AudioImporter)AssetImporter.GetAtPath(segment);if(!ai)throw new System.Exception("Missing segment "+segment);ai.defaultSampleSettings=settings;ai.forceToMono=true;ai.SaveAndReimport();x.narrationPages[part-1]=AssetDatabase.LoadAssetAtPath<AudioClip>(segment);}EditorUtility.SetDirty(x);}
 e.narrationPlayer=e.rig.GetComponent<AudioSource>();if(!e.narrationPlayer)e.narrationPlayer=e.rig.gameObject.AddComponent<AudioSource>();e.narrationPlayer.playOnAwake=false;e.narrationPlayer.spatialBlend=0;e.narrationPlayer.volume=.85f;
 foreach(var t in e.info.GetComponentsInChildren<Transform>(true).Where(t=>t.name.StartsWith("Story control")||t.name=="Story pagination"||t.name.StartsWith("Audio guide")).ToArray())if(t)Object.DestroyImmediate(t.gameObject);
 foreach(var label in e.info.GetComponentsInChildren<TMP_Text>(true).Where(t=>t!=e.exhibitTitle&&t!=e.exhibitDescription&&!t.GetComponentInParent<MuseumAction>(true)).ToArray())Object.DestroyImmediate(label.gameObject);
 e.info.localScale=Vector3.one*.82f;
 Text(e.info,"Audio guide brand","HERITAGE VR  /  COLLECTION AUDIO GUIDE",new Vector3(0,.91f,-.065f),new Vector2(1.78f,.12f),.48f);
 var background=e.info.Find("Information background");if(background)background.localScale=new Vector3(2.15f,2.1f,.035f);
 foreach(var a in e.info.GetComponentsInChildren<MuseumAction>(true)){var p=a.transform.localPosition;p.y=-.89f;a.transform.localPosition=p;}
 e.exhibitDescription.rectTransform.sizeDelta=new Vector2(1.78f,.66f);e.exhibitDescription.transform.localPosition=new Vector3(0,-.065f,-.065f);e.exhibitDescription.fontSizeMin=.6f;e.exhibitDescription.fontSizeMax=.8f;e.exhibitDescription.fontSize=.8f;
 e.storyStatus=Text(e.info,"Story pagination","STORY 1 / 3",new Vector3(0,.32f,-.065f),new Vector2(1.78f,.14f),.65f);
 var heading=e.info.Find("Collection heading");if(heading){var t=heading.GetComponent<TMP_Text>();t.text="HERITAGE VR";t.rectTransform.sizeDelta=new Vector2(1.1f,.12f);t.transform.localPosition=new Vector3(-.34f,.88f,-.065f);}
 e.exhibitTitle.transform.localPosition=new Vector3(0,.65f,-.065f);e.exhibitTitle.rectTransform.sizeDelta=new Vector2(1.78f,.30f);var accent=e.info.Find("Top accent");if(accent)accent.localPosition=new Vector3(0,1.05f,-.025f);
 e.audioStatus=Text(e.info,"Audio guide status","AUDIO GUIDE",new Vector3(0,-.45f,-.065f),new Vector2(1.78f,.12f),.60f);
 var progress=GameObject.CreatePrimitive(PrimitiveType.Cube);progress.name="Audio guide progress";progress.transform.SetParent(e.info,false);progress.transform.localPosition=new Vector3(-.89f,-.54f,-.065f);progress.transform.localScale=new Vector3(.001f,.012f,.01f);progress.GetComponent<Renderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/HeritageVR/Materials/Unified brushed brass.mat");Object.DestroyImmediate(progress.GetComponent<Collider>());e.audioProgress=progress.transform;
 Button(e.info,"PREVIOUS","storyPrevious",-.65f);e.listenLabel=Button(e.info,"LISTEN","listen",0);Button(e.info,"NEXT","storyNext",.65f);
 var foreground=AssetDatabase.LoadAssetAtPath<Material>("Assets/HeritageVR/Materials/Information text overlay.mat");foreground.SetFloat("_ZTestMode",8);foreground.renderQueue=3400;EditorUtility.SetDirty(foreground);foreach(var label in e.info.GetComponentsInChildren<TMP_Text>(true))label.fontSharedMaterial=foreground;
 e.exhibitDescription.text=e.selected.description.Split(new[]{"\n\n"},System.StringSplitOptions.None)[0];e.info.gameObject.SetActive(false);EditorUtility.SetDirty(e);EditorSceneManager.MarkSceneDirty(EditorSceneManager.GetActiveScene());EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());AssetDatabase.SaveAssets();
 }
 public static void Build(){Apply();QuestMuseumSetup.BuildAPK();}
}
